(5, 6, '_form', '<div class=\"elementor-form-fields-wrapper elementor-labels-\"><div class=\"elementor-field-type-text elementor-field-group elementor-column elementor-field-group-name elementor-col-100 elementor-field-required\"><label for=\"form-field-name\" class=\"elementor-field-label elementor-screen-only\">Name</label>[text* your-name id:form-field-name class:elementor-field class:elementor-size-lg class:elementor-field-textual placeholder \"Full Name\"]</div><div class=\"elementor-field-type-date elementor-field-group elementor-column elementor-field-group-field_81c37be elementor-col-100 elementor-field-required\"><label for=\"form-field-field_81c37be\" class=\"elementor-field-label elementor-screen-only\">Date of Birth</label>[date* your-dob id:form-field-field_81c37be class:elementor-field class:elementor-size-lg class:elementor-field-textual class:elementor-date-field placeholder \"Date of Birth\"]</div>\n<div class=\"elementor-field-type-text elementor-field-group elementor-column elementor-field-group-message elementor-col-100 elementor-field-required\"><label for=\"form-field-message\" class=\"elementor-field-label elementor-screen-only\">Mobile</label>[tel* your-mobile id:form-field-message class:elementor-field class:elementor-size-lg class:elementor-field-textual placeholder \"Mobile Number\"]</div><div class=\"elementor-field-type-email elementor-field-group elementor-column elementor-field-group-email elementor-col-100 elementor-field-required\"><label for=\"form-field-email\" class=\"elementor-field-label elementor-screen-only\">Email</label>[email* your-email id:form-field-email class:elementor-field class:elementor-size-lg class:elementor-field-textual placeholder \"Email Address\"]</div>[submit \"Welcome Aboard!\"]</div>'),
(6, 6, '_mail', 'a:9:{s:6:\"active\";b:1;s:7:\"subject\";s:27:\"[_site_title] \"[your-name]\"\";s:6:\"sender\";s:47:\"[_site_title] <wordpress@thegroup.josequal.net>\";s:9:\"recipient\";s:19:\"[_site_admin_email]\";s:4:\"body\";s:214:\"From: [your-name] [your-email]\nDate of Birth: [your-dob]\nmobile: [your-mobile]\nMessage Body:\n[your-message]\n\n-- \nThis is a notification that a contact form was submitted on your website ([_site_title] [_site_url]).\";s:18:\"additional_headers\";s:22:\"Reply-To: [your-email]\";s:11:\"attachments\";s:0:\"\";s:8:\"use_html\";b:1;s:13:\"exclude_blank\";b:1;}'),
(7, 6, '_mail_2', 'a:9:{s:6:\"active\";b:0;s:7:\"subject\";s:30:\"[_site_title] \"[your-subject]\"\";s:6:\"sender\";s:47:\"[_site_title] <wordpress@thegroup.josequal.net>\";s:9:\"recipient\";s:12:\"[your-email]\";s:4:\"body\";s:220:\"Message Body:\n[your-message]\n\n-- \nThis email is a receipt for your contact form submission on our website ([_site_title] [_site_url]) in which your email address was used. If that was not you, please ignore this message.\";s:18:\"additional_headers\";s:29:\"Reply-To: [_site_admin_email]\";s:11:\"attachments\";s:0:\"\";s:8:\"use_html\";b:1;s:13:\"exclude_blank\";b:1;}'),
