INSERT INTO `wp_postmeta` (`meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES
(1875, 298, 'points_content', '<ul>\r\n 	<li>THE Card points can be collected through buying from THE Group’s Stores (Cozmo, THE Department Store, Hamleys, Readers, and Cozmo Home).</li>\r\n 	<li>Every JOD 1 you spend in Cozmo will be transformed into <strong>10 points</strong></li>\r\n 	<li>Every JOD 1 you spend in THE Department Store, Hamleys, Readers, and Cozmo Home will be transformed into <strong>15 points.</strong></li>\r\n 	<li>After collecting 10,000 points, points will be transformed into vouchers to buy from any of THE Group brands.</li>\r\n 	<li>Reaching the 50,000 points will upgrade your card into “THE Gold Card” which will then allow you to exchange your points into vouchers and prizes.</li>\r\n</ul>'),
(1876, 298, '_points_content', 'field_68af2084e29fc'),
(1877, 298, 'other_benefits_title', 'Other Benefits'),
(1878, 298, '_other_benefits_title', 'field_68af2099e29fd'),
(1879, 298, 'other_benefits_content', 'Your ownership of THE Card also entitles you to benefit from a variety of discounts from our partners including: MedLabs, Abdali Hospital, Guinot Beauty Center, Freddy For Music, Family Taekwondo, Café Social, Casereccio, Live Sushi, Zen Gourmet, Tumayr, WashyWash, Kais Center, Curves Fitness Center.\r\n\r\n<strong>If you have any other inquiries about THE Card, don’t hesitate to call us at 06 5501240 – Ext: 1100, and we’ll be more than happy to assist.</strong>\r\n\r\n&nbsp;'),
