(2108, 339, '_boxes_1_title', 'field_68b04092998c6'),
(2109, 339, 'boxes_1_description', 'Find fresh seafood, chicken and meat from our butchery, or select one of our prime cuts of imported US, Australian and South African beef. Also available are a variety of pre-marinated, ready-to-cook, chicken and meat, perfect for weeknight meals.'),
(2110, 339, '_boxes_1_description', 'field_68b04098998c7'),
