(2334, 344, '_boxes_2_title', 'field_68b04092998c6'),
(2335, 344, 'boxes_2_description', 'Flavours from all over the globe can be found in our deli. We offer a wide selection of cheeses and cold cut deli meats imported from Italy, the UK, the Netherlands, Switzerland, Spain and more!'),
(2336, 344, '_boxes_2_description', 'field_68b04098998c7'),
