(2372, 14, 'about_footer_title', 'ABOUT THE GROUP'),
(2373, 14, '_about_footer_title', 'field_68b06633867fd'),
(2374, 14, 'about_footer_description', 'Founded in 2003, THE Group is a leading retail company in Jordan, home to trusted brands including Cozmo, THE Department Store, Hamleys, Readers Bookshop, and Cozmo Home. With a focus on quality, innovation, and customer experience, we continue to shape the future of retail.\r\nWhere trusted brands come together.\r\n\r\n'),
(2375, 14, '_about_footer_description', 'field_68b06641867fe'),
(2376, 348, 'first_section_image', '168'),
(2377, 348, '_first_section_image', 'field_68af05e2ab906'),
