(2391, 348, '_our_mission_title', 'field_68af06eeab90e'),
(2392, 348, 'our_mission_sub_text', '<span style=\"color: #d5a74f;\">To offer a valuable, multi-optional shopping experience through:</span>'),
(2393, 348, '_our_mission_sub_text', 'field_68af06f4ab90f'),
