(4024, 37, 'boxes_5_image', '635'),
(4025, 37, '_boxes_5_image', 'field_68b04081998c4'),
(4026, 37, 'boxes_5_title', 'Cozmo at The Ritz-Carlton Residences, Amman'),
(4027, 37, '_boxes_5_title', 'field_68b04092998c6'),
(4028, 37, 'boxes_5_description', 'As part of an exclusive partnership with Al Eqbal Real Estate Development and Hotels, THE Group has established a high-end Cozmo boutique convenience store within The Ritz-Carlton Residences Amman.\r\nTailored to meet the refined lifestyle of the residents, the store offers a curated selection of everyday essentials, available for direct purchase or doorstep delivery via phone orders.\r\nIn addition, residents can coordinate with our team to arrange full household shopping deliveries from Cozmo’s larger branches — combining luxury living with effortless convenience.\r\nPersonalised service. Premium shopping at your doorstep.'),
(4029, 37, '_boxes_5_description', 'field_68b04098998c7'),
