(4738, 514, 'header_description', 'Established in 2003, THE Group has grown into one of Jordan’s leading retail companies — built on a commitment to delivering exceptional customer service, curated experiences, and uncompromising quality.'),
(4739, 514, '_header_description', 'field_68af1637a75f0'),
(4740, 514, 'about_footer_title', 'About THE Group'),
(4741, 514, '_about_footer_title', 'field_68b06633867fd'),
(4742, 514, 'about_footer_description', 'Founded in 2003, THE Group is a leading retail company in Jordan, home to trusted brands including Cozmo, THE Department Store, Hamleys, Readers Bookshop, and Cozmo Home. With a focus on quality, innovation, and customer experience, we continue to shape the future of retail.\r\nWhere trusted brands come together.\r\n\r\n'),
(4743, 514, '_about_footer_description', 'field_68b06641867fe'),
