(5527, 549, '_download_section_image', 'field_68b040da998cf'),
(5528, 549, 'download_links_0_store_link', 'https://play.google.com/store/apps/details?id=jo.thegroup.cozmo&pli=1'),
(5529, 549, '_download_links_0_store_link', 'field_68b040c9998cd'),
