(7105, 615, 'header_description', 'Established in 2003, THE Group has grown into one of Jordan’s leading retail companies — built on a commitment to delivering exceptional customer service, curated experiences, and uncompromising quality.'),
(7106, 615, '_header_description', 'field_68af1637a75f0'),
(7107, 615, 'about_footer_title', 'ABOUT THE GROUP'),
(7108, 615, '_about_footer_title', 'field_68b06633867fd'),
(7109, 615, 'about_footer_description', 'Founded in 2003, THE Group is a leading retail company in Jordan, home to trusted brands including Cozmo, THE Department Store, Hamleys, Readers Bookshop, and Cozmo Home. With a focus on quality, innovation, and customer experience, we continue to shape the future of retail.\r\nWhere trusted brands come together.\r\n\r\n'),
(7110, 615, '_about_footer_description', 'field_68b06641867fe'),
(7111, 615, 'value_description', 'At THE Group, our values guide everything we do — from the way we work to the way we serve.'),
